job_placeholder = null
function addJobPlaceholder( update_only ) {
    if (update_only) 
        return;

    numActiveJobs = 0;

    $.each(job_refresh.activeJobs, function (index, job) {
        if (job && job.active)
            numActiveJobs++;
    });

    if (numActiveJobs <= 0) {
        if (!job_placeholder || !job_placeholder.length) {
            authenticated = false;

            $("#joblist").append(
                renderJob(createPlaceholderJob(), authenticated, true)
            );

            job_placeholder = $("#joblist .job-card[data-placeholder]");
        }
    } else if (job_placeholder && job_placeholder.length) {
        job_placeholder.remove();
        job_placeholder = null;
    }
}

/**
 * Function set as an interval to update all jobs from api
 */
function refreshJobs( update_only = false ) {
    let i = activeServers.length;

    $.each(activeServers, function (serverIndex, serverUrl) {
        $.getJSON(serverUrl + "/json?mode=joblist")
            .done(function (data) {
                i = refreshJobsSuccess(data, serverIndex, serverUrl, i);
            })
            .fail(function () {
                --i;
            })
            .always(function () {
                // Update job pipeline modal.
                $(document).trigger(
                    `arm:modal-update_${ARM.modal.jobs.pipeline.modal}`,
                    {}
                );

                // Update job details modal.
                $(document).trigger(
                    `arm:modal-update_${ARM.modal.jobs.details.modal}`,
                    {}
                );

                // Sort jobs after updates are processed
                sortJobs(update_only);
                removeInactiveJobs(update_only);
                addJobPlaceholder(update_only);
            });
    });
}

function startLogViewer(mode, logfile, interval = 3000, element_id = "#log_file_content") {
    const log_element = $(element_id);

    if (!__is_authenticated_simple()) {
        log_element.remove();
        return;
    }

    if (!logfile) {
        console.error(`Invalid log file: ${logfile}`);
        return;
    }

    if (!log_element.length){
        console.error(`Invalid log dom element`);
        return;
    }

    const element = log_element[0];
    const threshold = 5;

    let lastText = "";
    let initialized = false;
    let loading = false;
    let followBottom = true;

    function updateFollowBottom() {
        followBottom =
            element.scrollHeight - element.scrollTop - element.clientHeight <= threshold;
    }

    element.addEventListener("scroll", updateFollowBottom);

    function scrollToBottom() {
        if (followBottom)
            element.scrollTop = element.scrollHeight;
    }

    function fetchLog() {
        if (loading)
            return;

        loading = true;

        $.get("/logreader", {
            logfile: logfile,
            mode: mode
        })
        .done(function (data) {
            const text = data.content;
            let update = false;

            if (!initialized) {
                log_element.text(text);
                lastText = text;
                initialized = true;
                update = text.length > 0;
            } else if (text.startsWith(lastText) && text.length > lastText.length) {
                log_element.append(document.createTextNode(
                    text.substring(lastText.length)
                ));
                lastText = text;
                update = true;
            } else if (text !== lastText) {
                log_element.text(text);
                lastText = text;
                update = true;
            }

            if (update)
                scrollToBottom();
        })
        .fail(function (xhr, status, error) {
            console.error("Failed to refresh logfile:", status, error);
        })
        .always(function () {
            loading = false;
        });
    }

    fetchLog();

    const timer = window.setInterval(fetchLog, interval);

    // Return a cleanup function to stop polling and remove the listener.
    return function cleanup() {
        log_element.text("");
        window.clearInterval(timer);
        element.removeEventListener("scroll", updateFollowBottom);
    };
}

