		_modal.job_id = null;
		_modal.data = null;

		if (typeof _modal.log_viewer === "function")
			_modal.log_viewer();

		_modal.log_viewer = null;
	},

	load() {
		const _modal = ARM.modal.jobs.details;

		if (_modal.job_id == null)
			return;

		if (_modal.request)
			_modal.request.abort();

		const content = $(`${_modal.modal} .arm-modal-body`);

