                const $progress = $("<div>").addClass("sysinfo-progress");
                const $bar = $("<div>")
                    .addClass("sysinfo-progress-bar")
                    .css("width", this.clamp(percentage) + "%");

                if (percentage > 80)
                    $bar.addClass("danger");
                else if (percentage > 70)
                    $bar.addClass("warning");

                $progress.append($bar);

                const $legend = $("<div>").addClass("sysinfo-memory-legend");

                [
                    ["Total", total],
